from pathlib import Path
import re
p=Path('/home/ubuntu/diabetes-care-ar/client/src/pages/Home.tsx')
s=p.read_text()
# state for filters and activities
s=s.replace('  const [showReadingForm, setShowReadingForm] = useState(false);', '  const [showReadingForm, setShowReadingForm] = useState(false);\n  const [readingStatusFilter, setReadingStatusFilter] = useState("all");\n  const [readingDateFilter, setReadingDateFilter] = useState("all");\n  const [activities] = useState(() => [{ name: "مشي إلى العمل", type: "مشي", status: "مكتمل", date: "اليوم" }, { name: "صعود الدرج", type: "نشاط يومي", status: "مكتمل", date: "أمس" }, { name: "تمارين تمدد", type: "تمرين", status: "مخطط", date: "أمس" }]);')
# derived filtered readings
s=s.replace('  const latest = readings[0]?.value || 112;', '  const latest = readings[0]?.value || 112;\n  const filteredReadings = readings.filter((reading, index) => {\n    const statusMatch = readingStatusFilter === "all" || (readingStatusFilter === "normal" ? reading.value >= 70 && reading.value <= 140 : reading.value < 70 || reading.value > 140);\n    const dateMatch = readingDateFilter === "all" || (readingDateFilter === "today" ? index === 0 || reading.time.includes("اليوم") : !reading.time.includes("اليوم"));\n    return statusMatch && dateMatch;\n  });')
# pass filtered and activities
s=s.replace('<GlucoseSection readings={readings} latest={latest}', '<GlucoseSection readings={readings} filteredReadings={filteredReadings} activities={activities} readingStatusFilter={readingStatusFilter} setReadingStatusFilter={setReadingStatusFilter} readingDateFilter={readingDateFilter} setReadingDateFilter={setReadingDateFilter} latest={latest}')
# make nav pointer-aware
s=s.replace('className="mobile-bottom-nav fixed bottom-3 left-3 right-3 z-20 grid grid-cols-5 items-stretch gap-1', 'className="mobile-bottom-nav fixed bottom-3 left-3 right-3 z-20 grid grid-cols-5 items-stretch gap-1')
s=s.replace('backdrop-blur-xl lg:hidden" aria-label="التنقل السريع"', 'backdrop-blur-xl" aria-label="التنقل السريع"')
# remove visible AI watermark-like wording
s=s.replace('تحليل الطعام بالذكاء الاصطناعي', 'تحليل الطعام')
# replace whole GlucoseSection line block (single long line)
start=s.index('function GlucoseSection(')
end=s.index('\nfunction InteractiveGlucoseChart', start)
new='''function GlucoseSection({ readings, filteredReadings, activities, readingStatusFilter, setReadingStatusFilter, readingDateFilter, setReadingDateFilter, latest, latestStatus, showForm, setShowForm, readingValue, setReadingValue, readingContext, setReadingContext, onSubmit, dailyResult, dailyLoading, onRunDailyAnalysis }: any) { return <div className="fade-up"><SectionTitle eyebrow="قياساتك" title="سكر الدم" detail="سجّل، راقب، وصنّف قراءاتك وأنشطتك بمرور الوقت" action={<button onClick={() => setShowForm(true)} className="flex items-center gap-2 rounded-[14px] bg-[#0e7772] px-4 py-2.5 text-xs font-extrabold text-white shadow-lg shadow-[#0e7772]/15"><Plus size={15} /> قراءة جديدة</button>} /><div className="mb-6 grid gap-4 md:grid-cols-3"><div className="glass-dark p-5 text-white"><div className="flex items-center justify-between text-white/60"><span className="text-xs font-bold">آخر قراءة</span><Droplets size={18} /></div><div className="mt-5 flex items-baseline gap-2"><span className="font-mono text-4xl font-bold">{latest}</span><span className="text-xs">mg/dL</span></div><div className="mt-2 text-xs font-bold text-[#9ee6d2]">{latestStatus}</div></div><div className="glass p-5"><div className="flex items-center justify-between text-xs font-bold text-[#dcefee]"><span>متوسط الأسبوع</span><BarChart3 size={18} className="text-[#74e1c6]" /></div><div className="mt-5 font-mono text-3xl font-bold text-[#dcefee]">114 <span className="text-xs font-sans text-slate-400">mg/dL</span></div><div className="mt-2 text-[10px] font-semibold text-[#74e1c6]">↓ 8% من الأسبوع السابق</div></div><div className="glass p-5"><div className="flex items-center justify-between text-xs font-bold text-[#dcefee]"><span>النتائج المعروضة</span><Target size={18} className="text-[#f5b85f]" /></div><div className="mt-5 font-mono text-3xl font-bold text-[#dcefee]">{filteredReadings.length}<span className="text-lg"> قراءة</span></div><div className="mt-2 text-[10px] font-semibold text-[#f5b85f]">بعد التصفية الحالية</div></div></div><InteractiveGlucoseChart readings={filteredReadings.length ? filteredReadings : readings} /><div className="glass mb-6 p-5"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h3 className="text-sm font-extrabold text-[#dcefee]">تصفية السجل</h3><p className="mt-1 text-[10px] text-slate-400">اعرض القراءات حسب التاريخ أو الحالة.</p></div><button onClick={() => { setReadingStatusFilter("all"); setReadingDateFilter("all"); }} className="rounded-full border border-white/10 px-3 py-2 text-[10px] font-bold text-slate-400 transition hover:border-[#74e1c6]/60 hover:text-[#a9ebdb]">إعادة الضبط</button></div><div className="grid gap-3 sm:grid-cols-2"><select value={readingDateFilter} onChange={e => setReadingDateFilter(e.target.value)} className="rounded-[14px] border border-white/10 bg-white/[.06] px-3 py-3 text-xs font-bold text-[#dcefee] outline-none transition focus:border-[#74e1c6]"><option value="all">كل التواريخ</option><option value="today">اليوم</option><option value="older">أيام سابقة</option></select><select value={readingStatusFilter} onChange={e => setReadingStatusFilter(e.target.value)} className="rounded-[14px] border border-white/10 bg-white/[.06] px-3 py-3 text-xs font-bold text-[#dcefee] outline-none transition focus:border-[#74e1c6]"><option value="all">كل الحالات</option><option value="normal">ضمن النطاق العام</option><option value="attention">يحتاج مراجعة</option></select></div></div><div className="grid gap-6 lg:grid-cols-[1fr_1.2fr]"><div className="glass p-6">{showForm ? <><h3 className="mb-5 text-sm font-extrabold text-[#dcefee]">إضافة قراءة</h3><ReadingForm value={readingValue} setValue={setReadingValue} context={readingContext} setContext={setReadingContext} onSubmit={onSubmit} /></> : <div className="flex min-h-[280px] flex-col items-center justify-center text-center"><div className="mb-4 flex h-14 w-14 items-center justify-center rounded-[18px] bg-[#74e1c6]/10 text-[#74e1c6]"><Plus size={24} /></div><h3 className="font-extrabold text-[#dcefee]">أضف قراءتك التالية</h3><p className="mt-2 max-w-xs text-xs leading-6 text-slate-400">كل قراءة تساعدك على رؤية الصورة الكاملة.</p><button onClick={() => setShowForm(true)} className="mt-5 rounded-[13px] bg-[#74e1c6]/10 px-4 py-2 text-xs font-bold text-[#a9ebdb]">ابدأ التسجيل</button></div>}</div><div className="glass p-5"><div className="mb-4 flex items-center justify-between"><div><h3 className="text-sm font-extrabold text-[#dcefee]">السجل المصفّى</h3><p className="mt-1 text-[10px] text-slate-400">{filteredReadings.length} من {readings.length} قراءات</p></div><CircleHelp size={16} className="text-slate-400" /></div><div className="divide-y divide-white/10">{filteredReadings.length ? filteredReadings.map((reading: Reading, i: number) => <div key={`${reading.time}-${i}`} className="flex items-center gap-3 py-3"><div className={`flex h-9 w-9 items-center justify-center rounded-[12px] ${reading.value <= 140 && reading.value >= 70 ? "bg-[#74e1c6]/10 text-[#74e1c6]" : "bg-[#f5b85f]/10 text-[#f5b85f]"}`}><Droplets size={15} /></div><div className="min-w-0 flex-1"><div className="text-xs font-bold text-[#dcefee]">{reading.context}</div><div className="text-[10px] text-slate-400">{reading.time}</div></div><div className="font-mono text-sm font-bold text-[#dcefee]">{reading.value} <span className="font-sans text-[9px] text-slate-400">mg/dL</span></div></div>) : <div className="py-12 text-center text-xs text-slate-400">لا توجد قراءات تطابق الفلاتر.</div>}</div></div></div><div className="glass mt-6 p-5"><div className="mb-4 flex items-center gap-2"><Activity size={17} className="text-[#f5b85f]" /><div><h3 className="text-sm font-extrabold text-[#dcefee]">الأنشطة اليومية</h3><p className="mt-1 text-[10px] text-slate-400">سجل مبسّط للأنشطة المصنفة حسب الحالة والتاريخ.</p></div></div><div className="grid gap-3 sm:grid-cols-3">{activities.map((activity: any) => <div key={`${activity.name}-${activity.date}`} className="rounded-[15px] border border-white/10 bg-white/[.04] p-3"><div className="flex items-center justify-between"><span className="text-xs font-bold text-[#dcefee]">{activity.name}</span><span className={`rounded-full px-2 py-1 text-[9px] font-bold ${activity.status === "مكتمل" ? "bg-[#74e1c6]/10 text-[#a9ebdb]" : "bg-[#f5b85f]/10 text-[#f5d59b]"}`}>{activity.status}</span></div><div className="mt-2 text-[10px] text-slate-400">{activity.type} · {activity.date}</div></div>)}</div></div><div className="mt-6 rounded-[16px] border border-[#80633a]/30 bg-[#80633a]/10 p-4 text-[10px] leading-5 text-[#f0d5a2]"><Info size={14} className="ml-1 inline-block align-text-bottom" /> النطاقات تختلف من شخص لآخر. اعتمد خطة طبيبك واطلب المساعدة العاجلة عند الأعراض الشديدة.</div><DailyAnalysisCard readings={readings} result={dailyResult} loading={dailyLoading} onRun={onRunDailyAnalysis} /></div>; }
'''
s=s[:start]+new+s[end:]
p.write_text(s)

css=Path('/home/ubuntu/diabetes-care-ar/client/src/index.css')
content=css.read_text()
content=content.replace('.mobile-bottom-nav { direction: rtl; min-height: 66px; padding-bottom: max(8px, env(safe-area-inset-bottom)); }\n.mobile-bottom-nav-item { min-height: 50px; }', '.mobile-bottom-nav { direction: rtl; display: grid !important; width: calc(100% - 24px); min-height: 66px; padding-bottom: max(8px, env(safe-area-inset-bottom)); isolation: isolate; }\n.mobile-bottom-nav-item { min-height: 50px; position: relative; z-index: 1; transition: transform 180ms cubic-bezier(.23,1,.32,1), background-color 180ms ease, color 180ms ease, box-shadow 180ms ease; }\n.mobile-bottom-nav-item:hover, .mobile-bottom-nav-item:focus-visible { transform: translateY(-3px); color: #0b7772; background: rgba(116,225,198,.14); box-shadow: 0 6px 18px rgba(116,225,198,.16); outline: none; }\n.mobile-bottom-nav-item:active { transform: translateY(-1px) scale(.96); }\n.mobile-bottom-nav-item[aria-current="page"] { background: #e1f5f1; color: #0b7772; box-shadow: inset 0 -3px 0 #74e1c6, 0 5px 16px rgba(116,225,198,.14); }\n@media (min-width: 1024px) and (pointer: fine) { .mobile-bottom-nav { display: none !important; } }')
content=content.replace('max-width: 760px; margin-inline: auto;', 'max-width: 760px; margin-inline: auto;')
